#if APP_TESTS
using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Windows;using System.Windows.Controls;
namespace FileCompass {
 internal static class CompactUxTests {
  internal static int Run(string root){Directory.CreateDirectory(root);var log=new List<string>();int errors=0;try{L.ChangeLanguage("cs");foreach(var size in new[]{new Size(1280,800),new Size(1024,720)}){var w=new ConfigurationDialog(null){LayoutWorkArea=new Rect(-18000,-18000,size.Width,size.Height),Left=-17984,Top=-17984,Width=Math.Min(980,size.Width-32),WindowStartupLocation=WindowStartupLocation.Manual,ShowActivated=false};w.Show();for(int cat=0;cat<w.Sections.Items.Count;cat++){w.Sections.SelectedIndex=cat;NavigationTests.Wait(System.Threading.Tasks.Task.Delay(60));var pager=FluentUiTests.Children<SettingsPager>(w).Single();for(int page=0;page<pager.PageCount;page++){pager.Select(page);NavigationTests.Wait(System.Threading.Tasks.Task.Delay(30));w.UpdateLayout();bool fits=pager.ContentFits();if(!fits)errors++;log.Add((fits?"PASS ":"OVERFLOW ")+size.Width+" / "+w.Sections.Items[cat]+" / "+page);NextStageTests.Draw(w,Path.Combine(root,size.Width+"-"+cat+"-"+page+".png"));}}w.Close();}var main=new MainWindow(root,new ProgramSettings{AutoRefresh=false}){Left=-18000,Top=-18000,ShowActivated=false,WindowStartupLocation=WindowStartupLocation.Manual};main.Show();main.WindowState=WindowState.Maximized;NavigationTests.Wait(System.Threading.Tasks.Task.Delay(180));main.UpdateLayout();var screen=System.Windows.Forms.Screen.FromHandle(new System.Windows.Interop.WindowInteropHelper(main).Handle).WorkingArea;foreach(var button in FluentUiTests.Children<Button>(main).Where(x=>Convert.ToString(x.Tag)=="function-key")){bool visible=button.IsVisible&&button.PointToScreen(new Point(0,button.ActualHeight)).Y<=screen.Bottom+2;if(!visible)errors++;log.Add((visible?"PASS ":"OVERFLOW ")+"maximized footer "+button.Content);}NextStageTests.Draw(main,Path.Combine(root,"maximized.png"));main.Close();File.WriteAllLines(Path.Combine(root,"result.txt"),log.Concat(new[]{"Overflow pages: "+errors}));return errors==0?0:1;}catch(Exception ex){File.WriteAllText(Path.Combine(root,"result.txt"),String.Join("\n",log)+"\n"+ex);return 1;}}
 }
}
#endif
